## 1. Core Concept: History API + Modal State

The browser's back button triggers a `popstate` event. By pushing a new history state when the modal opens and listening for this event, you can intercept navigation and manage modal behavior.

### Basic Vanilla JS Example

```javascript
let modalHistoryState = {
  isModalOpen: false,
  previousUrl: null
};

// Open modal and push state
function openModal(modalId) {
  const modal = document.getElementById(modalId);
  modal.classList.add('open');

  // Save current state
  const previousState = history.state;

  // Push new state
  history.pushState({
    isModalOpen: true,
    previousUrl: previousState?.url || window.location.href,
    modalId: modalId
  }, '', window.location.href);

  modalHistoryState.isModalOpen = true;
}

// Close modal
function closeModal(modalId) {
  const modal = document.getElementById(modalId);
  modal.classList.remove('open');
  modalHistoryState.isModalOpen = false;
}

// Listen to popstate
window.addEventListener('popstate', (event) => {
  if (event.state?.isModalOpen && modalHistoryState.isModalOpen) {
    closeModal(event.state.modalId);
    history.back(); // Navigate to previous page
  } else if (modalHistoryState.isModalOpen) {
    closeModal();
  }
});

// Prevent default back button behavior if modal is open
document.getElementById('backButton').addEventListener('click', (e) => {
  if (modalHistoryState.isModalOpen) {
    e.preventDefault();
    closeModal(document.activeElement?.id);
  }
});
