## 2. Enhanced Version with Modal Stack

For apps that support nested or multiple modals, maintain a stack to track the order of opened modals.

```javascript
class ModalManager {
  constructor() {
    this.modalStack = [];
    this.setupEventListeners();
  }

  setupEventListeners() {
    window.addEventListener('popstate', (e) => this.handlePopState(e));
    document.addEventListener('click', (e) => {
      if (e.target?.classList.contains('close-modal') || e.target?.classList.contains('modal-overlay')) {
        this.closeModal();
      }
    });
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') this.closeModal();
    });
  }

  openModal(modalId) {
    const state = {
      isModalOpen: true,
      modalId: modalId,
      timestamp: Date.now()
    };
    this.modalStack.push(modalId);
    history.pushState(state, '', window.location.href);
    document.getElementById(modalId).classList.add('open');
  }

  closeModal() {
    if (this.modalStack.length === 0) return;

    const lastId = this.modalStack.pop();
    document.getElementById(lastId).classList.remove('open');

    if (this.modalStack.length === 0) {
      history.back();
    } else {
      history.pushState({
        isModalOpen: true,
        modalId: this.modalStack[this.modalStack.length - 1]
      }, '', window.location.href);
    }
  }

  handlePopState(event) {
    if (event.state?.isModalOpen && this.modalStack.length > 0) {
      this.closeModal();
    } else {
      history.back();
    }
  }

  isModalOpen() {
    return this.modalStack.length > 0;
  }
}

// Usage
const modalManager = new ModalManager();
modalManager.openModal('myModal');
```

